import 'package:cloud_firestore/cloud_firestore.dart';

class TenantRecord { TenantRecord(this.id, this.data); final String id; final Map<String, dynamic> data; }
class AgreementRecord { AgreementRecord(this.id, this.data); final String id; final Map<String, dynamic> data; }
class TenantRepository {
  TenantRepository(this._firestore); final FirebaseFirestore _firestore;
  Stream<List<TenantRecord>> watchTenants(String workspaceId) => _firestore.collection('tenants').where('workspaceId', isEqualTo: workspaceId).snapshots().map((value) => value.docs.map((item) => TenantRecord(item.id, item.data())).toList());
  Stream<List<AgreementRecord>> watchAgreements(String workspaceId) => _firestore.collection('rentalAgreements').where('workspaceId', isEqualTo: workspaceId).snapshots().map((value) => value.docs.map((item) => AgreementRecord(item.id, item.data())).toList());
  Future<String> createTenant(String workspaceId, Map<String, dynamic> data) async { final doc = _firestore.collection('tenants').doc(); await doc.set({...data, 'workspaceId': workspaceId, 'status': 'inactive', 'createdAt': FieldValue.serverTimestamp(), 'updatedAt': FieldValue.serverTimestamp()}); return doc.id; }
  Future<String> createAgreement(String workspaceId, Map<String, dynamic> data) async { final day = data['rentDueDay'] as int; if (day < 1 || day > 28) throw StateError('Rent due day must be between 1 and 28.'); final doc = _firestore.collection('rentalAgreements').doc(); await doc.set({...data, 'workspaceId': workspaceId, 'status': 'draft', 'createdAt': FieldValue.serverTimestamp(), 'updatedAt': FieldValue.serverTimestamp()}); return doc.id; }
  Future<void> activateAgreement(AgreementRecord agreement) => _firestore.runTransaction((tx) async { final data = agreement.data; final conflicts = await tx.get(_firestore.collection('rentalAgreements').where('workspaceId', isEqualTo: data['workspaceId']).where('unitId', isEqualTo: data['unitId']).where('status', isEqualTo: 'active')); if (conflicts.docs.any((item) => item.id != agreement.id)) throw StateError('This unit already has an active rental agreement.'); final unit = _firestore.collection('units').doc(data['unitId'] as String); final unitSnapshot = await tx.get(unit); if (!unitSnapshot.exists || unitSnapshot.data()?['status'] == 'inactive') throw StateError('This unit is not available.'); tx.update(_firestore.collection('rentalAgreements').doc(agreement.id), {'status': 'active', 'updatedAt': FieldValue.serverTimestamp()}); tx.update(unit, {'status': 'occupied', 'activeAgreementId': agreement.id, 'updatedAt': FieldValue.serverTimestamp()}); tx.update(_firestore.collection('tenants').doc(data['tenantId'] as String), {'status': 'active', 'updatedAt': FieldValue.serverTimestamp()}); });
  Future<void> endAgreement(AgreementRecord agreement, String status) => _firestore.runTransaction((tx) async { final data = agreement.data; tx.update(_firestore.collection('rentalAgreements').doc(agreement.id), {'status': status, 'updatedAt': FieldValue.serverTimestamp()}); tx.update(_firestore.collection('units').doc(data['unitId'] as String), {'status': 'vacant', 'activeAgreementId': null, 'updatedAt': FieldValue.serverTimestamp()}); final remaining = await tx.get(_firestore.collection('rentalAgreements').where('workspaceId', isEqualTo: data['workspaceId']).where('tenantId', isEqualTo: data['tenantId']).where('status', isEqualTo: 'active')); if (remaining.docs.every((item) => item.id == agreement.id)) tx.update(_firestore.collection('tenants').doc(data['tenantId'] as String), {'status': 'former', 'updatedAt': FieldValue.serverTimestamp()}); });
}
